{"command":"python3 << 'EOF'
import csv

# Spot check: verify a specific city's values match the source
# Let's check CH001C for year 2022
with open('outputs/t02_eurostat_raw.csv', 'r', newline='') as f:
    reader = csv.DictReader(f)
    source_data = {}
    for row in reader:
        if row['city_id'] == 'CH001C' and row['year'] == '2022':
            source_data[row['indicator_id']] = row['value']

print("Source data for CH001C, 2022:")
for k, v in sorted(source_data.items()):
    print(f"  {k}: {v}")

# Now check the matrix
with open('outputs/t11_city_indicator_matrix.csv', 'r', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['city_id'] == 'CH001C' and row['year'] == '2022':
            print("\nMatrix row for CH001C, 2022:")
            for k, v in row.items():
                print(f"  {k}: {v}")
            break

# Verify match
print("\nVerification:")
for ind in source_data:
    if source_data[ind] == row[ind]:
        print(f"  {ind}: MATCH")
    else:
        print(f"  {ind}: MISMATCH - source={source_data[ind]}, matrix={row[ind]}")
EOF"}

